sys_variable_value.value:
(function execute(inputs, outputs) {
    var tr = inputs.trigger_record;
    var appSysId = tr.sys_id.toString();
    var candSysId = tr.candidate.toString();
    var reqSysId = tr.requisition.toString();

    // ── 1. Gather context for question generation ──
    var roleTitle = tr.requisition.role_title.toString();
    var level = tr.requisition.level.getDisplayValue();
    var department = tr.requisition.department.getDisplayValue();
    var reqSkills = tr.requisition.required_skills.toString();
    var resumeText = tr.resume.toString();

    // ── 2. Get screening result for this application ──
    var screenGr = new GlideRecord('x_snc_aegis_screening_result');
    screenGr.addQuery('application', appSysId);
    screenGr.addQuery('screening_status', 'COMPLETED');
    screenGr.orderByDesc('screened_at');
    screenGr.setLimit(1);
    screenGr.query();

    var matchedSkills = '';
    var missingSkills = '';
    var fitScore = 0;
    var transferableSkills = '';

    if (screenGr.next()) {
        matchedSkills = screenGr.getValue('matched_skills') || '';
        missingSkills = screenGr.getValue('missing_skills') || '';
        fitScore = parseInt(screenGr.getValue('fit_score'), 10) || 0;
        transferableSkills = screenGr.getValue('transferable_skills') || '';
    }

    // ── 3. Generate tailored questions (TEMPLATE FALLBACK) ──
    // When you integrate with AI Agent 3 (Phase 4A), the agent generates these.
    var questions = [];

    // Technical depth questions based on matched skills
    if (matchedSkills) {
        var matched = matchedSkills.split(',');
        for (var i = 0; i < Math.min(matched.length, 3); i++) {
            var skill = matched[i].trim();
            questions.push({
                category: 'Technical Depth',
                question: 'Describe a complex project where you leveraged ' + skill + '. What architectural decisions did you make and why?',
                rubric: 'Look for: depth of understanding, trade-off analysis, real-world application. Score 1-5.'
            });
        }
    }

    // Gap assessment questions based on missing skills
    if (missingSkills) {
        var missing = missingSkills.split(',');
        for (var j = 0; j < Math.min(missing.length, 2); j++) {
            var gap = missing[j].trim();
            questions.push({
                category: 'Gap Assessment',
                question: 'This role requires ' + gap + '. While it is not listed in your experience, how would you approach learning and applying it?',
                rubric: 'Look for: learning agility, self-awareness, concrete plan. Score 1-5.'
            });
        }
    }

    // Behavioral / situational
    questions.push({
        category: 'Behavioral',
        question: 'Tell me about a time you had a significant disagreement with a colleague about a technical approach. How did you resolve it?',
        rubric: 'Look for: conflict resolution, communication, respect for differing opinions. Score 1-5.'
    });

    questions.push({
        category: 'Problem Solving',
        question: 'Walk me through how you would debug a critical production issue that is affecting 10% of users intermittently.',
        rubric: 'Look for: systematic approach, prioritization, communication with stakeholders. Score 1-5.'
    });

    // Level-specific
    if (level === 'Senior' || level === 'Lead') {
        questions.push({
            category: 'Leadership',
            question: 'How do you approach mentoring junior engineers? Give a specific example of how you helped someone grow.',
            rubric: 'Look for: investment in others, teaching methodology, measurable growth. Score 1-5.'
        });
    }

    // Format as structured text
    var questionSetText = '=== TAILORED INTERVIEW QUESTIONS ===\n';
    questionSetText += 'Role: ' + roleTitle + ' (' + level + ')\n';
    questionSetText += 'Candidate Fit Score: ' + fitScore + '/100\n';
    questionSetText += 'Generated: ' + new GlideDateTime().getDisplayValue() + '\n\n';

    for (var q = 0; q < questions.length; q++) {
        questionSetText += 'Q' + (q + 1) + ' [' + questions[q].category + ']\n';
        questionSetText += questions[q].question + '\n';
        questionSetText += 'RUBRIC: ' + questions[q].rubric + '\n\n';
    }

    // ── 4. Create Interview record ──
    var intGr = new GlideRecord('x_snc_aegis_interview');
    intGr.initialize();
    intGr.setValue('application', appSysId);
    intGr.setValue('candidate', candSysId);
    intGr.setValue('interview_type', 'TECHNICAL'); // Default; recruiter can change
    intGr.setValue('interview_status', 'DRAFT');
    intGr.setValue('outcome', 'PENDING');
    intGr.setValue('question_set', questionSetText);
    intGr.setValue('synthesis_status', 'PENDING');

    var intSysId = intGr.insert();

    // ── 5. Log ──
    var logger = new x_snc_aegis.AEGISDecisionLogger();
    logger.logAction(
        'Interview Orchestrator',
        'INTERVIEW_SCHEDULE',
        appSysId,
        reqSysId,
        'Candidate: ' + tr.candidate.full_name.toString() +
            ' | Fit: ' + fitScore + ' | Matched: ' + matchedSkills.substring(0, 100) +
            ' | Missing: ' + missingSkills.substring(0, 100),
        questions.length + ' tailored questions generated | Interview: ' + intSysId,
        null,
        'Questions personalized based on screening scores and skill gaps'
    );

    outputs.interview_sys_id = intSysId;
    outputs.question_count = questions.length;

})(inputs, outputs);

